  var SHIELD_PLANS = [
    { key:'open', name:'OPEN', ko:'차단하지 않음', price:0,
      keep:['contour','age','sex','emotion','impression','personality'],
      desc:'시야를 차단하지 않습니다.',
      foot:'기본 제공' },
    { key:'veil', name:'VEIL', ko:'부분 차단', price:12000,
      keep:['contour','age'],
      desc:'시야를 부분적으로 차단합니다.',
      foot:'가장 많이 선택' },
    { key:'blackout', name:'BLACKOUT', ko:'전면 블러', price:39000,
      keep:[],
      desc:'타인의 시야에서 당신의 얼굴을 블러 처리 합니다.',
      foot:'완전 차단' }
  ];

  var DEC_BASE = 0.10;                       // 전부 차단해도 남는 결정도
  var FULL_DAILY = VIEW_LAYERS.reduce(function(a,l){ return a+l.cost; }, 0); // 6,100
  var FULL_VISION = VIEW_LAYERS.reduce(function(a,l){ return a+l.vision; }, 0); // 41

  var S = {
    profile: { job:null, age:null, sex:null },
    blocked: {},          // 시야 필터: key -> true(차단)
    expose: {},           // 노출 필터: key -> true(허용). 구독 플랜이 결정한다.
    shieldPlan: 'open',   // 노출 차단 구독 플랜
    budgetDaily: 6100,
    spent: 0,             // 오늘 누적 관측세
    saved: 0,             // 오늘 누적 절약
    passed: 0,            // 통과 건수
    blockedCount: 0,      // 차단 건수
    byLayer: {},          // key -> {pass, block}
    monthDayIndex: 13,    // 이번 달 경과 일수(오늘 이전)
    yearDayIndex: 194,
    forced: false,        // 예산 초과로 전면 블러 처리된 상태
    gazeShieldUntil: 0,    // 타인 시선 일시 차단 만료 시각(ms)
    holdIntensity: 100     // 저장된 유지 강도(%) — HOLD 패널에서 '저장하기'로만 반영된다
 };
  EXPOSE.forEach(function(e){ S.expose[e.key] = true; });   // 기본값: 전부 허용 = 결정도 0.71
  VIEW_LAYERS.forEach(function(l){ S.byLayer[l.key] = { pass:0, block:0 }; });

  /* =========================================================
     계산
     ========================================================= */

  function isBlocked(k){ return S.forced || !!S.blocked[k]; }
  function blockedList(){ return VIEW_LAYERS.filter(function(l){ return S.blocked[l.key]; }); }
  function allowedList(){ return VIEW_LAYERS.filter(function(l){ return !S.blocked[l.key]; }); }
  function dailyProjTax(){ return allowedList().reduce(function(a,l){ return a+l.cost; }, 0); }
  function dailyProjSaved(){ return FULL_DAILY - dailyProjTax(); }
  function visionPct(){ return 100 - blockedList().reduce(function(a,l){ return a+l.vision; }, 0); }
  function decidednessFull(){ // 유지 강도 100% 기준 결정도 — 슬라이더 미리보기의 기준값
    if(typeof gazeShieldActive === 'function' && gazeShieldActive()) return DEC_BASE;
    return EXPOSE.reduce(function(a,e){ return a + (S.expose[e.key] ? e.dec : 0); }, DEC_BASE);
 }
  function decidedness(){
    if(typeof gazeShieldActive === 'function' && gazeShieldActive()) return DEC_BASE;
    var full = decidednessFull();
    return DEC_BASE + (full - DEC_BASE) * (S.holdIntensity/100);
 }
  function planOf(){
    for(var i=0;i<SHIELD_PLANS.length;i++){ if(SHIELD_PLANS[i].key === S.shieldPlan) return SHIELD_PLANS[i]; }
    return SHIELD_PLANS[0];
 }
  function applyPlan(k){
    S.shieldPlan = k;
    var p = planOf();
    EXPOSE.forEach(function(e){ S.expose[e.key] = p.keep.indexOf(e.key) >= 0; });
 }
  function holdFeeFull(){ // 유지 강도 100% 기준 연 구독료(만원)
    return planOf().price * 12 / 10000;
 }
  function holdFee(){ // 만원/년 — 저장된 유지 강도가 반영된 실제 요금
    return holdFeeFull() * (S.holdIntensity/100);
 }
  function annualTax(){ return dailyProjTax() * 365; }
  function annualSaved(){ return dailyProjSaved() * 365; }
  function leftoverPct(){
    if(!S.budgetDaily) return 100;
    return Math.max(0, Math.round((1 - S.spent/S.budgetDaily) * 100));
 }
  function monthSpent(){ return dailyProjTax()*S.monthDayIndex + S.spent; }
  function monthBudget(){ return S.budgetDaily ? S.budgetDaily*30 : 0; }
  function monthLeftoverPct(){
    if(!monthBudget()) return 100;
    return Math.max(0, Math.round((1 - monthSpent()/monthBudget()) * 100));
 }

  function won(v){ return '₩' + Math.round(v).toLocaleString('ko-KR'); }
  function manwon(v){ return (Math.round(v*10)/10).toFixed(1).replace(/\.0$/,'') + '만원'; }
  function wonToMan(v){ return manwon(v/10000); }
  function escapeHtml(s){ var d=document.createElement('div'); d.textContent=s; return d.innerHTML; }

