  /* ---------- AR HUD 화면 맞춤 ----------
     이제 폰트를 줄여 억지로 맞추지 않는다 — 내용이 세로로 넘치면
     컨테이너의 overflow:auto로 자연스럽게 스크롤한다. 원본 크기를 그대로 유지. */
  function OBSERVER_fitScreen(container, content){
    if(!container || !content) return;
    content.style.zoom = '1';
 }
  function OBSERVER_fitAll(){
    OBSERVER_fitScreen(onboarding, ob);
    OBSERVER_fitScreen(document.getElementById('system'),  document.getElementById('sysMenu'));
 }
  window.OBSERVER_fitAll = OBSERVER_fitAll;
  window.addEventListener('resize', function(){ requestAnimationFrame(OBSERVER_fitAll); });

  var obEyeRaf = null;
  var OB_DISPOSE = [];
  function setContent(html){
    if(obEyeRaf){ cancelAnimationFrame(obEyeRaf); obEyeRaf = null; }
    OB_DISPOSE.forEach(function(f){ try{ f(); }catch(e){} });
    OB_DISPOSE = [];
    ob.innerHTML = html; onboarding.scrollTop = 0;
    requestAnimationFrame(function(){ OBSERVER_fitScreen(onboarding, ob); navBind(); });
 }

  /* ---------- 온보딩 뒤로가기 ----------
     각 단계는 들어올 때 자기 이전 단계를 등록한다.
     토큰은 뒤로 간 뒤에 이전 단계의 타이머가 되살아나는 것을 막는다. */
  var OB_PREV = null, OB_TOKEN = 0;
  var OB_TOTAL = 11;
  function obPaintIndicator(step){
    var wrap = document.getElementById('obIndicator');
    var dots = document.getElementById('obDots');
    var count = document.getElementById('obStepCount');
    if(!wrap || !dots || !count) return;
    if(!dots.children.length){
      for(var i=1;i<=OB_TOTAL;i++){ var d=document.createElement('i'); d.className='ob-dot'; dots.appendChild(d); }
 }
    step = Math.max(1, Math.min(OB_TOTAL, step || 1));
    count.textContent = String(step).padStart(2,'0') + ' / ' + String(OB_TOTAL).padStart(2,'0');
    Array.prototype.forEach.call(dots.children,function(d,i){
      d.className='ob-dot' + (i+1===step?' on':(i+1<step?' done':''));
 });
 }
  function stageEnter(prev, step){
    OB_PREV = prev || null;
    OB_TOKEN++;
    var b = document.getElementById('obBack');
    if(b) b.hidden = !OB_PREV;
    obPaintIndicator(step);
    return OB_TOKEN;
 }
  (function(){
    var b = document.getElementById('obBack');
    if(!b) return;
    b.addEventListener('click', function(){
      if(!OB_PREV) return;
      var p = OB_PREV;
      shutUp();
      p();
 });
 })();
  function eye(){ return window.EYE || { active:false, closed:false, score:0, face:false }; }
  var EYE_HOLD_MS = 3000;

  /* ================= 음성 안내 =================
     눈을 감으면 화면을 볼 수 없으므로, 그동안의 UI는 소리다. */
  // 클릭할 때마다 자동으로 낭독하는 동작은 없앴다.
  // 다만 캘리브레이션 안내와 three-two-one 카운트다운은 진행에 필요하므로 남긴다.
  // 전부 끄고 싶으면 우측 하단 음성 칩을 누른다.
  var AUD = { on:true, voice:null, voiceEn:null, talking:false };

  function pickVoice(){
    if(!window.speechSynthesis) return;
    var vs = window.speechSynthesis.getVoices() || [];
    // 자연스러운(뉴럴·클라우드) 보이스를 우선한다.
    function rank(list){
      var natural = /neural|premium|enhanced|natural|siri|google|yuna|heami|sunhi|injoon|nara|wavenet|online/i;
      var poor    = /compact|espeak|eloquence|novelty/i;
      var good    = list.filter(function(v){ return !poor.test(v.name); });
      var pool    = good.length ? good : list;
      return pool.filter(function(v){ return natural.test(v.name); })[0]
          || pool.filter(function(v){ return v.localService === false; })[0]   // 클라우드 보이스
          || pool[0] || null;
 }
    AUD.voice   = rank(vs.filter(function(v){ return /^ko/i.test(v.lang); }));
    AUD.voiceEn = rank(vs.filter(function(v){ return /^en/i.test(v.lang); }));
 }
  // 영어 안내(gathering/verified/321)는 반드시 영어 보이스로. 없으면 그 자리에서 다시 찾는다.
  // 보이스를 못 지정하면 한국어 기본 보이스가 영어를 한국어 발음으로 읽는다.
  function enVoice(){
    var vs = (window.speechSynthesis && window.speechSynthesis.getVoices()) || [];
    // 캐시가 현재 목록에 실제로 존재할 때만 신뢰한다 (교체되면 stale 참조가 무시돼 한국어로 샌다).
    if(AUD.voiceEn && vs.indexOf(AUD.voiceEn) !== -1) return AUD.voiceEn;
    pickVoice();
    vs = (window.speechSynthesis && window.speechSynthesis.getVoices()) || [];
    if(AUD.voiceEn && vs.indexOf(AUD.voiceEn) !== -1) return AUD.voiceEn;
    return vs.filter(function(v){ return /^en/i.test(v.lang); })[0] || null;
 }
  if(window.speechSynthesis){
    pickVoice();
    window.speechSynthesis.addEventListener('voiceschanged', pickVoice);
 }

  function paintAud(){
    var c = document.getElementById('audChip');
    if(!c) return;
    c.classList.toggle('on', AUD.on);
    c.classList.toggle('talking', AUD.talking);
    document.getElementById('audLbl').textContent = AUD.on ? '음성 안내 켜짐' : '음성 안내 꺼짐';
 }

  /* ================= 음색 =================
     자연스러운 낭독을 위해 음정·속도를 기본값에 가깝게 두고,
     문장 단위로 끊어 억양이 살아나게 한다. 기기음(캐리어·신호음)은 그대로 둔다. */
  var MACHINE = { pitch:1.0, rate:1.0 };
  var AC = null, humOsc = null, humGain = null;

  function ac(){
    if(!AC){
      try{ AC = new (window.AudioContext || window.webkitAudioContext)(); }
      catch(e){ return null; }
 }
    if(AC.state === 'suspended'){ try{ AC.resume(); }catch(e){} }
    return AC;
 }

  // 안내 시작을 알리는 2음 신호
  function blip(){
    var c = ac(); if(!c) return;
    var t0 = c.currentTime;
    [[1180, 0], [1760, 0.05]].forEach(function(p){
      var o = c.createOscillator(), g = c.createGain();
      o.type = 'square';
      o.frequency.setValueAtTime(p[0], t0 + p[1]);
      g.gain.setValueAtTime(0.0001, t0 + p[1]);
      g.gain.exponentialRampToValueAtTime(0.03, t0 + p[1] + 0.006);
      g.gain.exponentialRampToValueAtTime(0.0001, t0 + p[1] + 0.055);
      o.connect(g); g.connect(c.destination);
      o.start(t0 + p[1]); o.stop(t0 + p[1] + 0.08);
 });
 }

  // 말하는 동안 아래에 깔리는 캐리어 — 기기가 돌아가는 소리
  function humOn(){
    var c = ac(); if(!c || humOsc) return;
    humOsc = c.createOscillator();
    var det = c.createOscillator();
    humGain = c.createGain();
    var lp = c.createBiquadFilter();
    lp.type = 'lowpass'; lp.frequency.value = 220;
    humOsc.type = 'sawtooth'; humOsc.frequency.value = 57;
    det.type = 'sine'; det.frequency.value = 85.5;
    humGain.gain.setValueAtTime(0.0001, c.currentTime);
    humGain.gain.linearRampToValueAtTime(0.016, c.currentTime + 0.18);
    humOsc.connect(lp); det.connect(lp); lp.connect(humGain); humGain.connect(c.destination);
    humOsc.start(); det.start();
    humOsc._det = det;
 }
  function humOff(){
    if(!humOsc || !AC) return;
    var o = humOsc, g = humGain, t = AC.currentTime;
    humOsc = null; humGain = null;
    try{
      g.gain.cancelScheduledValues(t);
      g.gain.setValueAtTime(g.gain.value, t);
      g.gain.linearRampToValueAtTime(0.0001, t + 0.22);
      o.stop(t + 0.26); if(o._det) o._det.stop(t + 0.26);
 }catch(e){}
 }

  function shutUp(){
    if(window.speechSynthesis) window.speechSynthesis.cancel();
    humOff();
    AUD.talking = false; paintAud();
 }

  // TTS가 기호를 그대로 읽지 않도록 말로 바꾼다
  function spClean(t){
    return String(t)
      .replace(/₩\s?([\d,]+)/g, function(m,n){ return n.replace(/,/g,'') + '원'; })
      .replace(/([\d.]+)\s?%/g, '$1퍼센트')
      .replace(/\s*·\s*/g, ', ')
      .replace(/\s{2,}/g, ' ')
      .trim();
 }

  // 문장 단위로만 끊는다. 쉼표는 문장 안에 남겨 억양이 자연스럽게 이어진다.
  function chunkText(t){
    return String(t)
      .replace(/([.?!])\s+/g, '$1\u0000')
      .split('\u0000')
      .map(function(s){ return s.trim(); })
      .filter(Boolean);
 }

  // 안내가 끝나는 시점을 알아야 하는 곳이 있다. opts.onEnd 로 알린다.
  // 말할 수 없는 상태면 false 를 돌려준다.
  function say(text, opts){
    opts = opts || {};
    // 낭독 전면 중단: 캘리브레이션 안내와 321 카운트(keep:true)만 소리로 남긴다.
    if(!opts.keep) return false;
    if(!AUD.on || !text || !window.speechSynthesis) return false;
    var en = (opts.lang === 'en');
    var body = en ? String(text) : spClean(text);
    var parts = en ? [body] : chunkText(body);
    if(!parts.length) return false;

    function fire(){
      if(!AUD.on) return;
      if(opts.blip !== false) blip();
      parts.forEach(function(seg, i){
        var u = new SpeechSynthesisUtterance(seg);
        u.lang = en ? 'en-US' : 'ko-KR';
        try{
          var pick = en ? enVoice() : AUD.voice;
          if(pick) u.voice = pick;
 }catch(e){ AUD.voice = null; AUD.voiceEn = null; }
        u.rate  = (opts.rate || 1) * MACHINE.rate;
        u.pitch = MACHINE.pitch;   // 문장 단위 낭독이라 억양이 자연스럽게 살아난다
        if(i === 0) u.onstart = function(){ AUD.talking = true; humOn(); paintAud(); };
        u.onend = u.onerror = function(){
          var live = window.speechSynthesis.speaking || window.speechSynthesis.pending;
          AUD.talking = live;
          if(!live) humOff();
          paintAud();
          if(i === parts.length-1 && opts.onEnd){
            var done = opts.onEnd; opts.onEnd = null; done();
 }
 };
        window.speechSynthesis.speak(u);
 });
 }

    if(opts.interrupt){
      window.speechSynthesis.cancel();
      // 크롬은 cancel 직후의 speak 를 삼키는 일이 있다
      setTimeout(fire, 60);
 } else {
      fire();
 }
    return true;
 }

  // 숫자는 쉼표를 빼야 TTS가 끊지 않고 읽는다
  function spWon(v){ return Math.round(v) + '원'; }
  function spPct(v){ return Math.round(v) + '퍼센트'; }
  function spMan(v){ return (Math.round(v*10)/10).toFixed(1).replace(/\.0$/,'') + '만원'; }

  /* =========================================================
     CTA 조작 — 마우스 클릭으로 진행, 끄덕임·음성은 보조

     '다음/뒤로'는 마우스로 바로 클릭해 진행한다. 넘어갈 때는
     음성으로 "다음" 또는 "뒤로"를 말해준다. 끄덕임/음성 트리거는
     보조 수단으로 그대로 남아 있고, 별도 안내문은 띄우지 않는다.

       - 다음(primary): 현재 화면에서 비활성이 아닌 .ghost-btn
       - 뒤로(back)   : #obBack
       - 끄덕임        : window.EYE.nodSeq 증가 → 다음
       - 음성          : "다음/계속/시작/응/그래/네" → 다음,
                         "뒤로/취소/이전"           → 뒤로
     ========================================================= */
  var NAV = {
    on:false, primary:null, back:null,
    nodSeen:0, shakeSeen:0, guided:false, voiceLbl:'다음',
    lastTapEl:null, lastTapAt:0, bypass:false
 };

  // 현재 온보딩 화면의 CTA 를 다시 스캔한다. setContent 직후에 한 번,
  // 그리고 navPollNod 가 매 프레임 다시 부른다 — 버튼이 disabled 였다가
  // 칩 선택으로 활성화되는 화면(직업·나이·성별)에서도 곧바로 잡히도록.
  function navRescan(){
    if(!NAV.on) return;
    var buttons = ob.querySelectorAll('.ghost-btn');
    var primary = null;
    Array.prototype.forEach.call(buttons, function(b){
      if(!primary && !b.disabled && b.offsetParent !== null) primary = b;
 });
    var back = document.getElementById('obBack');
    var backEl = (back && !back.hidden) ? back : null;

    var changed = (primary !== NAV.primary) || (backEl !== NAV.back);
    NAV.primary = primary || null;
    NAV.back = backEl;
    if(!changed) return;                         // 바뀐 게 없으면 힌트 재생성 안 함

    NAV.voiceLbl = (primary && /다음/.test(primary.textContent)) ? '다음' :
                   (primary ? primary.textContent.trim().split(/\s+/)[0] : '다음');

    var old = ob.querySelector('.cta-hint'); if(old) old.remove();   // 끄덕임/음성 안내는 표시하지 않는다
 }

  // setContent 직후 호출 — 새 화면이므로 카운터 기준선을 리셋하고 스캔한다.
  function navBind(){
    if(!NAV.on) return;
    NAV.primary = null; NAV.back = null;         // 강제 재구성
    NAV.nodSeen   = (window.EYE && window.EYE.nodSeq)   || 0;
    NAV.shakeSeen = (window.EYE && window.EYE.shakeSeq) || 0;
    navRescan();
 }

  // 실제 진행 — 뒤로/다음으로 넘어갈 때 음성으로 라벨을 말한다.
  function navGo(kind, el){
    el = el || (kind === 'back' ? NAV.back : NAV.primary);
    if(!el || el.disabled) return;
    var navLabel = (el.textContent || '').trim() || (kind === 'back' ? '뒤로' : '다음');
    say(navLabel, { keep:true, interrupt:true, blip:false });
    NAV.primary = NAV.back = null;            // 중복 실행 방지
    NAV.bypass = true;                         // 가로채기 우회
    el.click();
    NAV.bypass = false;
 }

  // 고개 조작(끄덕임=다음 / 도리도리=뒤로) 기능 제거 — CTA 재스캔만 유지.
  var navScanAt = 0;
  function navPollNod(){
    if(NAV.on){
      var now = performance.now();
      if(now - navScanAt > 200){ navScanAt = now; navRescan(); }
    }
    requestAnimationFrame(navPollNod);
 }

  // 음성 인식 — 크롬 계열의 webkitSpeechRecognition
  var VOICE = { rec:null, want:false, active:false, retryTimer:null, retryCount:0 };
  function voiceSupported(){
    return !!(window.SpeechRecognition || window.webkitSpeechRecognition);
 }
  function vcSet(txt, state){ // state: 'listen' | 'off' | 'err'
    var chip = document.getElementById('vcChip');
    if(!chip) return;
    chip.hidden = false;
    chip.classList.toggle('listening', state === 'listen');
    chip.classList.toggle('off', state !== 'listen');
    var lbl = document.getElementById('vcLbl');
    if(lbl) lbl.textContent = txt;
 }
  function voiceStart(){
    if(!NAV.on || !voiceSupported() || VOICE.active) return;
    // 보안 컨텍스트가 아니면(예: file://) 마이크가 아예 안 열린다
    if(!window.isSecureContext && location.protocol !== 'http:'){
      vcSet('음성 불가 · localhost로 여세요', 'err'); return;
 }
    var SR = window.SpeechRecognition || window.webkitSpeechRecognition;
    var rec = new SR();
    rec.lang = 'ko-KR'; rec.continuous = true; rec.interimResults = false;
    rec.onresult = function(ev){
      for(var i=ev.resultIndex; i<ev.results.length; i++){
        var t = (ev.results[i][0].transcript || '').replace(/\s/g,'');
        // 음성으로 화면을 자동 진행하지 않는다. 이동은 버튼(또는 명시적 손 클릭)으로만 한다.
        // 음성 인식은 상태 표시/향후 확장용으로만 유지한다.
        if(/(뒤로|이전|취소|백|다음|계속|시작|확인|넘어가|응|그래|네|예|오케이|오키|고)/.test(t)){
          return;
        }
 }
 };
    rec.onend = function(){
      VOICE.active = false;
      if(!VOICE.want) return;
      if(VOICE.retryTimer) clearTimeout(VOICE.retryTimer);
      var delay = Math.min(4000, 400 * Math.pow(2, Math.min(3, VOICE.retryCount++)));
      VOICE.retryTimer = setTimeout(function(){ VOICE.retryTimer = null; voiceStart(); }, delay);
    };
    rec.onerror = function(e){
      VOICE.active = false;
      var err = e && e.error;
      if(err === 'not-allowed' || err === 'service-not-allowed'){
        VOICE.want = false; vcSet('마이크 차단됨 · 눌러서 재시도', 'err');
 } else if(err === 'no-speech' || err === 'aborted'){
        /* 무시하고 onend 에서 재시작 */
 } else if(err === 'network'){
        vcSet('음성 네트워크 오류 · 재시도', 'err');
 } else {
        vcSet('음성 오류 · 눌러서 재시도', 'err');
 }
 };
    try{
      rec.start(); VOICE.rec = rec; VOICE.active = true; VOICE.want = true; VOICE.retryCount = 0;
      vcSet('음성 명령 듣는 중', 'listen');
 }catch(e){ VOICE.active = false; vcSet('음성 시작 실패 · 눌러서 재시도', 'err'); }
 }
  function voiceStop(){
    VOICE.want = false;
    if(VOICE.retryTimer){ clearTimeout(VOICE.retryTimer); VOICE.retryTimer = null; }
    VOICE.retryCount = 0;
    try{ if(VOICE.rec) VOICE.rec.stop(); }catch(e){}
    var chip = document.getElementById('vcChip');
    if(chip){ chip.classList.remove('listening'); chip.hidden = true; }
 }
  // 칩을 누르면 수동 재시도 (사용자 제스처가 있어야 마이크를 여는 브라우저 대응)
  (function(){
    var chip = document.getElementById('vcChip');
    if(chip) chip.addEventListener('click', function(){
      if(!voiceSupported()) return;
      VOICE.want = true; VOICE.active = false;
      try{ if(VOICE.rec) VOICE.rec.stop(); }catch(e){}
      setTimeout(voiceStart, 120);
 });
 })();

  // 온보딩 전체에 클릭 위임 — 어느 화면의 CTA든 여기서 가로챈다
  function navInit(){
    if(NAV.on) return;
    NAV.on = true;
    onboarding.addEventListener('click', function(ev){
      if(NAV.bypass) return;                   // navGo 가 실행한 클릭은 통과
      var b = ev.target.closest && ev.target.closest('.ghost-btn, #obBack');
      if(!b || b.disabled) return;
      // 진행 성격의 CTA(다음/뒤로)는 마우스 클릭으로 바로 넘어간다.
      var isBack = (b.id === 'obBack');
      ev.preventDefault(); ev.stopPropagation();
      navGo(isBack ? 'back' : 'next', b);
 }, true);
    navPollNod();
    handCursorLoop();
    if(!voiceSupported()){
      vcSet('음성 미지원', 'off');
 }
 }

  /* ================= 손 커서 + pinch 클릭 =================
     EYE.hand(검지 끝, 정규화 좌표)를 화면 좌표로 옮겨 커서를 그린다.
     CTA(다음/뒤로) 근처에 가면 자석처럼 스냅되고, 집으면(pinchSeq↑)
     스냅된 버튼을 실행한다. 스냅 대상이 없으면 커서 아래 요소를 클릭. */
  var HAND = { pinchSeen:0, target:null, lastClickAt:0, COOLDOWN:800, slider:null,
    wasPinching:false, dragging:false, dragStartY:0, dragScrollStart:0, dragTarget:null, dragMoved:false, pinchStartY:0, pinchButton:null };
  // 손 커서 아래 요소에 마우스 hover 이벤트를 흘려보내, 마우스 hover 로 동작하는
  // UI(결정도 구간 강조 등)가 손동작에도 반응하게 한다.
  var HAND_HOVER_EL = null;
  function handHover(px, py){
    var raw = (px >= 0 && py >= 0) ? document.elementFromPoint(px, py) : null;
    var t = (raw && raw.closest)
      ? raw.closest('.dcx-seg, .vfx-row, .flt-row, .plan, .chip, .tab, #sysList li, [role="button"], button')
      : null;
    if(t !== HAND_HOVER_EL){
      if(HAND_HOVER_EL) HAND_HOVER_EL.dispatchEvent(new MouseEvent('mouseleave', { bubbles:false }));
      HAND_HOVER_EL = t;
      if(t) t.dispatchEvent(new MouseEvent('mouseenter', { bubbles:false }));
 }
    if(t) t.dispatchEvent(new MouseEvent('mousemove', { bubbles:true, clientX:px, clientY:py }));
 }
  // 손이 화면 위/아래 가장자리 근처에 머물면 현재 열려 있는 컨테이너를 그 방향으로 스크롤한다.
  // (콘텐츠가 세로로 넘칠 때, 클릭/드래그 없이 손 위치만으로 스크롤할 수 있게 한다)
  function handScrollTarget(){
    // 현재 보이는 스크롤 컨테이너를 우선한다.
    // 온보딩 단계와 시스템 패널이 동시에 존재해도 실제로 넘치는 쪽을 찾아간다.
    var candidates = [];
    if(inPanel){ candidates.push(document.getElementById('sysPanel')); }
    if(inSystem){ candidates.push(document.getElementById('system')); }
    if(!inPanel && !inSystem){ candidates.push(onboarding); }
    for(var i=0;i<candidates.length;i++) {
      var el = candidates[i];
      if(el && el.scrollHeight > el.clientHeight + 1) return el;
    }
    return candidates[0] || null;
 }
  var HAND_SCROLL_EDGE = 100, HAND_SCROLL_MAXSPD = 12;
  function handEdgeScroll(px, py, vh){
    var target = handScrollTarget();
    if(!target || target.scrollHeight <= target.clientHeight) return;
    var dy = 0;
    if(py < HAND_SCROLL_EDGE){
      dy = -HAND_SCROLL_MAXSPD * (HAND_SCROLL_EDGE - py) / HAND_SCROLL_EDGE;
 } else if(py > vh - HAND_SCROLL_EDGE){
      dy = HAND_SCROLL_MAXSPD * (py - (vh - HAND_SCROLL_EDGE)) / HAND_SCROLL_EDGE;
 }
    if(dy) target.scrollTop += dy;
 }
  // 주먹을 쥔 채로 위/아래로 끌면(핀치-드래그) 화면을 그 방향으로 스크롤한다 —
  // 실제로 화면을 손으로 잡아당기는 듯한 제스처. CTA/슬라이더에 스냅된 상태에서는
  // 시작하지 않는다(기존 클릭 동작을 그대로 유지하기 위함).
  function handDragScroll(rawPy, px, py){
    var pinchNow = !!(window.EYE && window.EYE.hand && window.EYE.hand.pinch);
    if(pinchNow && !HAND.wasPinching){
      HAND.dragTarget = handScrollTarget();
      HAND.dragStartY = rawPy;
      HAND.dragScrollStart = HAND.dragTarget ? HAND.dragTarget.scrollTop : 0;
      HAND.dragMoved = false;
      HAND.pinchStartY = rawPy;
      HAND.pinchButton = HAND.slider ? null : HAND.target;
      HAND.dragging = false;
    } else if(pinchNow && HAND.dragTarget){
      var moved = Math.abs(rawPy - HAND.pinchStartY);
      var threshold = Math.max(12, Math.min(30, window.innerHeight * 0.018));
      if(moved > threshold && HAND.dragTarget.scrollHeight > HAND.dragTarget.clientHeight){
        HAND.dragging = true;
        HAND.dragMoved = true;
        HAND.dragTarget.scrollTop = HAND.dragScrollStart + (HAND.dragStartY - rawPy) * Math.max(1, window.innerHeight * 0.85);
      }
    } else if(!pinchNow && HAND.wasPinching){
      var shouldClick = !HAND.dragMoved && !!HAND.pinchButton;
      var clickTarget = HAND.pinchButton;
      var nowMs = Date.now();
      HAND.dragging = false; HAND.dragTarget = null; HAND.dragMoved = false; HAND.pinchButton = null;
      if(shouldClick && nowMs - HAND.lastClickAt >= HAND.COOLDOWN){
        HAND.lastClickAt = nowMs;
        if(clickTarget === NAV.back){ navGo('back'); }
        else if(clickTarget === NAV.primary){ if(!NAV.primary.disabled) navGo('next'); }
        else {
          var releaseEl = document.elementFromPoint(px, py);
          var clickable = releaseEl && releaseEl.closest && releaseEl.closest(
            '.ep-btn, .epx, .bd-modal-x, .bd-demo-btn, .bd-demo-sw button, ' +
            'button, [role="button"], .chip, .plan, .vfx-row, .flt-row, .tab, ' +
            '.ent.blurred, #sysList li, .panel-back, .speak-btn');
          if(clickable){ NAV.bypass = true; clickable.click(); NAV.bypass = false; }
        }
      }
    }
    HAND.wasPinching = pinchNow;
  }
  function handCursorLoop(){
    var cur = document.getElementById('handCursor');
    var E = window.EYE;
    var expEl = document.getElementById('experience');
    var expOn = expEl && !expEl.hidden;   // 온보딩 밖(월드·시스템·팝업)에서도 손 조작이 살아 있어야 한다
    if((NAV.on || expOn) && cur && E && E.hand && E.hand.present){
      var vw = window.innerWidth, vh = window.innerHeight;
      var px = E.hand.x * vw, py = E.hand.y * vh;
      var rawPy = (E.hand.scrollY != null ? E.hand.scrollY : E.hand.y) * vh;   // 스냅/고정과 무관한 실제 손 Y — 드래그 스크롤용

      // 슬라이더가 있으면 트랙 근처에서 커서가 트랙 위로 붙는다(가로 조작 전용)
      var slider = document.getElementById('bdRange');
      var onSlider = false, sRect = null;
      if(slider){
        sRect = slider.getBoundingClientRect();
        // 트랙 세로 중심에서 ±60px, 가로로는 트랙 범위 ±40px 안이면 슬라이더 조작 영역
        var band = 60, padX = 40;
        if(py > sRect.top - band && py < sRect.bottom + band &&
           px > sRect.left - padX && px < sRect.right + padX){
          onSlider = true;
 }
 }

      // 스냅 대상 찾기 — 현재 화면의 CTA 중 커서에 가장 가까운 것
      var targets = [];
      if(NAV.primary) targets.push(NAV.primary);
      if(NAV.back) targets.push(NAV.back);
      var best = null, bestD = 1e9, SNAP = 90;
      targets.forEach(function(el){
        var r = el.getBoundingClientRect();
        var cx = r.left + r.width/2, cy = r.top + r.height/2;
        var dx = px - cx, dy = py - cy;
        var inside = px>=r.left && px<=r.right && py>=r.top && py<=r.bottom;
        var d = inside ? 0 : Math.hypot(dx, dy);
        if(d < bestD){ bestD = d; best = { el:el, cx:cx, cy:cy, d:d }; }
 });

      var snapped = best && bestD < SNAP;
      // 슬라이더 영역이 CTA 스냅보다 우선 — 트랙 위로 커서를 끌어올린다
      if(onSlider){
        snapped = false; HAND.target = null; HAND.slider = slider;
        var trackY = sRect.top + sRect.height/2;
        px = Math.max(sRect.left, Math.min(sRect.right, px));  // 트랙 밖으로 안 나가게
        py = py*0.4 + trackY*0.6;
        cur.classList.add('snap');
 } else {
        HAND.slider = null;
        if(snapped){ px = px*0.45 + best.cx*0.55; py = py*0.45 + best.cy*0.55; }
        HAND.target = snapped ? best.el : null;
        cur.classList.toggle('snap', !!snapped);
 }

      cur.hidden = false;
      cur.style.left = px + 'px';
      cur.style.top  = py + 'px';
      cur.classList.toggle('pinch', !!E.hand.pinch);
      handHover(px, py);   // 손 위치에 따라 hover UI 를 갱신
      handEdgeScroll(px, rawPy, vh);   // 화면 위/아래 가장자리 근처면 스크롤
      handDragScroll(rawPy, px, py);           // 쥔 채로 끌면(핀치-드래그) 그 방향으로 스크롤

      // 핀치 시작은 CTA를 즉시 실행하지 않는다. 이동이 없으면 손을 펴는 순간 클릭하고, 충분히 이동하면 드래그 스크롤로 처리한다.
      if(E.pinchSeq > HAND.pinchSeen){
        HAND.pinchSeen = E.pinchSeq;
        if(HAND.slider){
          var nowMs = Date.now();
          if(nowMs - HAND.lastClickAt >= HAND.COOLDOWN){
            HAND.lastClickAt = nowMs;
            var sr = HAND.slider.getBoundingClientRect();
            var ratio = (px - sr.left) / (sr.width || 1);
            ratio = Math.max(0, Math.min(1, ratio));
            var mn = parseInt(HAND.slider.min,10), mx = parseInt(HAND.slider.max,10);
            var stp = parseInt(HAND.slider.step,10) || 1;
            var raw = mn + ratio * (mx - mn);
            var val = mn + Math.round((raw - mn) / stp) * stp;
            HAND.slider.value = val;
            HAND.slider.dispatchEvent(new Event('input', { bubbles:true }));
            HAND.slider.dispatchEvent(new Event('change', { bubbles:true }));
            HAND.pinchButton = null;
          }
        }
      }
 } else if(cur){
      cur.hidden = true; HAND.target = null; HAND.slider = null;
      HAND.dragging = false; HAND.wasPinching = false; HAND.dragTarget = null; HAND.dragMoved = false; HAND.pinchButton = null;
      handHover(-1, -1);   // 손이 사라지면 hover 해제
      if(E && E.pinchSeq) HAND.pinchSeen = E.pinchSeq;   // 손이 사라진 동안의 pinch는 무시
 }
    requestAnimationFrame(handCursorLoop);
 }

  function stageWelcome(){
    stageEnter(null,1);
    // 표지에서는 단계 표시(01/12)와 뒤로가기를 숨긴다
    var ind = document.getElementById('obIndicator');
    if(ind) ind.style.display = 'none';
    var bk = document.getElementById('obBack');
    if(bk) bk.hidden = true;
    setContent(
      '<div class="eyelids" aria-hidden="true"><i class="top"></i><i class="bot"></i></div>' +
      '<div class="wel eye-wake">' +
        '<div class="wel-sub eng" style="color:#E03319;">IN-SIGHT OS</div>' +
        '<h1 class="wel-mark eng">OBSERVER</h1>' +
        '<div class="wel-tag">개인용 관측 운영체제를 통해 관측세를 최적화해보세요.</div>' +
        '<button class="ghost-btn" id="bWelcome">시작하기</button>' +
      '</div>'
    );
    var go = document.getElementById('bWelcome');
    if(go) go.onclick = function(){
      if(ind) ind.style.display = '';   // 다음 화면부터 단계 표시 복구
      stageCamera();
 };
 }

  function stageCamera(){
    stageEnter(null,1);
    setContent(
      '<div class="breathe-dot"></div>' +
      '<div class="voice-line">지금부터 <br> 시선을 스캔하겠습니다.</div>' +
      '<button class="ghost-btn" id="bCam">카메라를 허용합니다</button>' +
      '<div class="cam-err" id="camErr"' + (envNote() ? '' : ' style="display:none;"') + '>' + envNote() + '</div>'
    );
    var btn = document.getElementById('bCam');
    var err = document.getElementById('camErr');
    btn.onclick = function(){
      btn.disabled = true; btn.textContent = '눈을 찾는 중…';
      var wait = 0;
      (function go(){
        if(!window.OBSERVER_startEye){
          if(wait++ > 120){ fail('눈 인식 모듈을 불러오지 못했습니다.'); return; }
          setTimeout(go, 100); return;
 }
        window.OBSERVER_startEye().then(function(ok){
          if(ok){ navInit(); stageObserver(); }
          else { fail((window.EYE && window.EYE.error) || '카메라를 열 수 없습니다.'); }
 }).catch(function(){ fail('카메라를 열 수 없습니다.'); });
 })();
 };
    function fail(msg){
      btn.disabled = false; btn.textContent = '다시 시도';
      err.style.display = 'block';
      var why = envNote();
      if(!why && (window.EYE && window.EYE.errCode === 'NotAllowedError')){
        why = '브라우저 주소창의 카메라 아이콘에서 이 사이트를 허용으로 바꾼 뒤 다시 시도하세요.';
 }
      err.innerHTML = msg + (why ? '<br>' + why : '') +
        '<br>카메라 없이는 진행할 수 없습니다. 허용한 뒤 다시 시도하세요.<br>' + envDiag();
 }
 }

  function inFrame(){
    try { return window.self !== window.top; } catch(e){ return true; }
 }
  function framePolicyBlocked(){
    if(!inFrame()) return false;
    try{
      if(document.featurePolicy && document.featurePolicy.allowsFeature)
        return !document.featurePolicy.allowsFeature('camera');
 }catch(e){}
    return true; // 프레임 안이면 일단 차단으로 가정
 }
  function insecure(){
    return location.protocol === 'file:' || !window.isSecureContext;
 }
  function frameMsg(){
    return '<b style="color:var(--text); font-weight:400;">미리보기 프레임 안에서는 카메라가 차단됩니다.</b><br>' +
           '이 파일을 내려받아 브라우저 탭에서 직접 열면 동작합니다.';
 }
  function insecureMsg(){
    return '파일을 직접 연 상태라 카메라가 막힐 수 있습니다. 폴더에서 ' +
           '<code style="font-family:var(--mono)">python3 -m http.server</code> 를 실행하고 ' +
           'localhost 로 여세요.';
 }
  function envNote(){
    if(framePolicyBlocked()) return frameMsg();
    if(insecure()) return insecureMsg();
    return '';
 }
  function envDiag(){
    return '<span style="color:var(--faint); font-family:var(--mono); font-size:var(--fs-body);">' +
      location.protocol + ' · ' + (inFrame() ? 'iframe' : 'top') +
      ' · secure ' + (window.isSecureContext ? 'y' : 'n') + '</span>';
 }

  /* ---------- 시선 캘리브레이션 ----------
     감음 3초 → 뜸 3초 → 정보 수집 → 확인 */

  function calibPhase(instr, wantClosed, next){
    var tk = OB_TOKEN;
    setContent(
      '<div class="calib-instr">' + instr + '</div>' +
      '<div class="calib-num" id="calibNum"></div>' +
      '<div class="calib-hint" id="calibHint"></div>' +
      '<div class="calib-track"><i id="calibBar"></i></div>'
    );

    var num = document.getElementById('calibNum');
    var hintEl = document.getElementById('calibHint');
    var bar = document.getElementById('calibBar');
    var held = 0, prev = 0, shown = 0, spoken = 0, started = false;
    // '눈을 감아주세요'는 3,2,1 (3초). '눈을 떠주세요'는 2,1 (2초)만 센다.
    var COUNT = wantClosed ? 3 : 2;
    var DUR = COUNT * 1000;
    var EN = ['','One','Two','Three'];

    // 안내 뒤 카운트를 또렷하게 센다.
    var spoke = say(instr, { interrupt:true, onEnd:begin, rate:0.95, keep:true });
    var guard = setTimeout(begin, spoke ? 1700 : 500);

    function begin(){
      if(started || tk !== OB_TOKEN) return;
      started = true;
      clearTimeout(guard);
      prev = performance.now();
      obEyeRaf = requestAnimationFrame(tick);
 }

    function tick(now){
      if(tk !== OB_TOKEN) return;
      var dt = now - prev; prev = now;
      var E = eye();
      var ok = E.face && (wantClosed ? E.closed : !E.closed);

      if(ok){
        held += dt;
        hintEl.textContent = '';
 } else {
        held = 0; spoken = 0;
        hintEl.textContent = !E.face
          ? '얼굴이 보이지 않습니다'
          : (wantClosed ? '아직 눈을 감아주세요' : '눈을 떠주세요');
 }

      var t = Math.min(1, held/DUR);
      bar.style.width = (t*100).toFixed(1) + '%';

      var n = Math.max(1, COUNT - Math.floor(held/1000));
      if(n !== shown){ shown = n; num.innerHTML = '<span>' + n + '</span>'; }
      if(ok && n !== spoken){ spoken = n; say(EN[n], {interrupt:true, rate:1.0, lang:'en', blip:false, keep:true}); }

      if(t >= 1){ next(); return; }
      obEyeRaf = requestAnimationFrame(tick);
 }
 }

  function stageObserver(){
    stageEnter(stageCamera,2);
    calibPhase('눈을 감아주세요', true, stageLookAt);
 }

  function stageLookAt(){
    stageEnter(stageObserver,3);
    calibPhase('눈을 떠주세요', false, stageGathering);
 }

  function stageGathering(){
    var tk = stageEnter(stageObserver,3);
    setContent('<div class="gather-word calib-eng" id="gatherWord"></div>');
    var word = 'GATHERING INFORMATION';
    var host = document.getElementById('gatherWord');
    host.innerHTML = word.split('').map(function(c, i){
      return c === ' ' ? '<b style="width:.4em; display:inline-block;">&nbsp;</b>'
                       : '<b style="animation-delay:' + (i*0.055).toFixed(2) + 's">' + c + '</b>';
 }).join('');
    say('gathering information', {interrupt:true, lang:'en', keep:true});
    setTimeout(function(){ if(tk === OB_TOKEN) stageVerified(); }, 2600);
 }

  function stageVerified(){
    var tk = stageEnter(stageObserver,3);
    var hex = function(n){ var o=''; for(var i=0;i<n;i++) o += '0123456789ABCDEF'[Math.floor(Math.random()*16)]; return o; };
    setContent(
      '<div class="verify-mark">' +
        '<div class="vf-stage">' +
          '<img class="vf-icon" src="data:image/png;base64," alt="Verified"/>' +
          '<div class="vf-scan"></div>' +
        '</div>' +
        '<div class="verify-word calib-eng" id="vfWord">&nbsp;</div>' +
        '<div class="vf-meta">ID ' + hex(4) + '-' + hex(4) + ' · <b>LOCKED</b></div>' +
      '</div>' +
      '<div class="vf-flash"></div>'
    );
    scrambleTo(document.getElementById('vfWord'), 'VERIFIED', 560, 1000);
    say('verified', {interrupt:true, lang:'en', keep:true});
    setTimeout(function(){ if(tk === OB_TOKEN) stageHandGuide(); }, 2500);
 }

  /* 손 조작 안내 — VERIFIED 다음, 결정도 화면 전. 여기서 실제로
     주먹을 쥐어 '계속'을 눌러보게 해서 조작법을 몸으로 익히게 한다. */
  /* 손 조작 안내 아이콘 — 펼친 손(커서), 주먹, 머리 */
  var HG_ICON_CURSOR =
    '<img class="hg-svg" src="data:image/png;base64," alt="" />';
  var HG_ICON_FIST =
    '<img class="hg-svg" src="data:image/png;base64," alt="" />';
  var HG_ICON_HEAD =
    '<svg class="hg-svg" viewBox="0 0 32 32" fill="none" stroke="currentColor" stroke-width="1.6" ' +
      'stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">' +
      '<circle cx="16" cy="13" r="6"/>' +
      '<path d="M9 26 c1.5-4 4-6 7-6 s5.5 2 7 6"/>' +
      // 끄덕임·도리도리 방향 화살표
      '<path d="M16 3 v2 M15 4 l1-1 1 1"/>' +
      '<path d="M27 13 h2 M28 12 l1 1-1 1"/>' +
    '</svg>';

  function stageHandGuide(){
    stageEnter(stageObserver,3);
    var hasHand = !!(window.EYE && window.EYE.handReady);
    setContent(
      '<div class="voice-line">아래와 같이 조작하세요.</div>' +
      '<div class="hg">' +
        '<div class="hg-row">' +
          '<div class="hg-ic">' + HG_ICON_CURSOR + '</div>' +
          '<div class="hg-tx"><b>손을 펴고 화면에 비추면 커서가 따라옵니다.</b></div>' +
        '</div>' +
        '<div class="hg-row">' +
          '<div class="hg-ic">' + HG_ICON_FIST + '</div>' +
          '<div class="hg-tx"><b>주먹을 쥐어 클릭할 수 있습니다.</b></div>' +
        '</div>' +
      '</div>' +
      '<div class="micro" id="hgState">' +
        (hasHand ? ''
                 : '손 인식을 준비 중입니다. 지금은 다음 버튼을 눌러 넘어가세요.') +
      '</div>' +
      '<button class="ghost-btn" id="bHand">다음</button>'
    );
    document.getElementById('bHand').onclick = stageDecidedness;

    // 손 모델이 뒤늦게 준비되면 안내문을 갱신
    if(!hasHand){
      var tk = OB_TOKEN, tries = 0;
      var iv = setInterval(function(){
        if(tk !== OB_TOKEN || tries++ > 60){ clearInterval(iv); return; }
        if(window.EYE && window.EYE.handReady){
          clearInterval(iv);
          var st = document.getElementById('hgState');
          if(st) st.textContent = '';
 }
 }, 500);
      OB_DISPOSE.push(function(){ clearInterval(iv); });
 }
 }

  /* 글자를 무작위로 굴리다 왼쪽부터 자리를 잡는 디코딩 연출 */
  function scrambleTo(el, word, delay, dur){
    if(!el) return;
    var POOL = 'ABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789';
    var t0 = null;
    function frame(now){
      if(!el.isConnected) return;
      if(t0 === null) t0 = now;
      var t = Math.min(1, (now - t0) / dur);
      var settled = Math.floor(Math.pow(t, .78) * word.length + 0.0001);
      var out = '';
      for(var i=0;i<word.length;i++){
        out += (i < settled) ? word.charAt(i) : POOL.charAt(Math.floor(Math.random()*POOL.length));
 }
      el.textContent = out;
      if(t < 1) requestAnimationFrame(frame);
      else el.textContent = word;
 }
    setTimeout(function(){ if(el.isConnected) requestAnimationFrame(frame); }, delay);
 }

  /* ---------- 결정도 구간 ---------- */
  var DEC_BANDS = [
    { lo:0.00, hi:0.30, name:'VANISHED',
      desc:'형태를 관측할 수 없는 상태' },
    { lo:0.30, hi:0.55, name:'FLUID',
      desc:'형태가 고정되지 않은 채 끊임 없이 변화하는 상태' },
    { lo:0.55, hi:0.78, name:'SETTLED',
      desc:'하나의 안정적인 형태를 갖게 된 상태' },
    { lo:0.78, hi:1.00, name:'FIXED',
      desc:'현재의 형태가 영구적으로 굳어진 상태' }
  ];
  var SCANNED_DEC = 0.71;

  function bandOf(v){
    for(var i=0;i<DEC_BANDS.length;i++){
      if(v < DEC_BANDS[i].hi || i === DEC_BANDS.length-1) return DEC_BANDS[i];
 }
    return DEC_BANDS[0];
 }


  // 반원 게이지 대신 0.00–1.00 계측 레일. 구간 폭이 곧 실제 범위 폭이다.
  function decRailHtml(v){
    var segs = DEC_BANDS.map(function(b, i){
      var on = bandOf(v) === b;
      var left = (b.lo * 100), w = ((b.hi - b.lo) * 100);
      return '<div class="dcx-seg' + (on ? ' on' : '') + '" data-i="' + i + '" tabindex="0" ' +
             'style="left:calc(' + left + '% + ' + (i ? 1 : 0) + 'px); ' +
             'width:calc(' + w + '% - ' + (i && i < DEC_BANDS.length-1 ? 2 : 1) + 'px);">' +
               '</div>';
 }).join('');
    return '<div class="dcx">' +
      '<div class="vfx-head">' +
        '<span class="vfx-kicker">당신의 결정도</span>' +
        '<span class="vfx-rule"></span>' +
      '</div>' +
      '<div class="dcx-big">' +
        '<div class="dcx-val" id="dcxVal">0.00</div>' +
        '<div class="dcx-band"><em>BAND</em><span id="dcxBand">' + bandOf(v).name + '</span></div>' +
      '</div>' +
      '<div class="dcx-rail" id="dcxRail">' + segs +
        '<div class="dcx-mark" id="dcxMark" style="left:0%;">' +
          '<b id="dcxMarkVal">0.00</b><i></i><u>YOU</u></div>' +
      '</div>' +
      '<div class="dcx-scale">' +
        '<span style="left:0%">0.00</span><span style="left:30%">0.30</span>' +
        '<span style="left:55%">0.55</span><span style="left:78%">0.78</span>' +
        '<span style="left:100%">1.00</span>' +
      '</div>' +
    '</div>';
 }

  // 레전드는 필터 화면과 같은 문법으로 쌓는다
  function buildDecLegend(host, v){
    var active = bandOf(v);
    DEC_BANDS.forEach(function(b, i){
      var on = (b === active);
      var row = vfxRow({
        i: i + 1, name: b.name, code: '', desc: b.desc,
        figure: b.lo.toFixed(2) + '–' + b.hi.toFixed(2), unit: '',
        pt: on ? '현재 구간' : '', on: on, cut: false
 });
      row.classList.add('dec-row');
      row.removeAttribute('role');
      row.removeAttribute('aria-checked');
      row.setAttribute('data-i', i);
      host.appendChild(row);
 });
 }

  // 현재 구간은 늘 켜져 있고, 나머지는 손을 얹은 동안만 두 번째 색으로 밝아진다
  function wireDecLegend(v){
    var rows = document.querySelectorAll('#decLegend .vfx-row');
    var segs = document.querySelectorAll('.dcx-seg');
    var activeIdx = DEC_BANDS.indexOf(bandOf(v));

    function hoverBand(i){
      Array.prototype.forEach.call(rows, function(r, j){
        r.classList.toggle('on', j === activeIdx);
        r.classList.toggle('hov', i !== null && j === i && j !== activeIdx);
        var tag = r.querySelector('.vfx-pt');
        if(tag) tag.textContent = (j === activeIdx) ? '현재 구간' : '';
 });
      Array.prototype.forEach.call(segs, function(sg, j){
        sg.classList.toggle('on', j === activeIdx);
        sg.classList.toggle('hov', i !== null && j === i && j !== activeIdx);
 });
 }

    // 화면이 뜬 순간 커서가 우연히 구간 위에 있어도 현재 구간이 유지되도록,
    // 실제 움직임(mousemove)이 있어야 호버로 인정한다
    var armed = false;
    function bind(el, i){
      el.addEventListener('mousemove', function(){ armed = true; hoverBand(i); });
      el.addEventListener('mouseenter', function(){ if(armed) hoverBand(i); });
      el.addEventListener('mouseleave', function(){ hoverBand(null); });
      el.addEventListener('focus', function(){ hoverBand(i); });
      el.addEventListener('blur', function(){ hoverBand(null); });
 }
    Array.prototype.forEach.call(rows, bind);
    Array.prototype.forEach.call(segs, bind);
    var legend = document.getElementById('decLegend');
    legend.addEventListener('mouseleave', function(){ hoverBand(null); });
    var rail = document.getElementById('dcxRail');
    if(rail) rail.addEventListener('mouseleave', function(){ hoverBand(null); });
    hoverBand(null);
 }

  // 0.00 에서 실제 값까지 굴러 올라간다
  function countUpDec(els, target, dur){
    els = els.filter(Boolean);
    if(!els.length) return;
    var t0 = null;
    function step(now){
      if(!els[0].isConnected) return;
      if(t0 === null) t0 = now;
      var t = Math.min(1, (now - t0) / dur);
      var e = 1 - Math.pow(1 - t, 3);
      var txt = (t < 1 ? target * e : target).toFixed(2);
      els.forEach(function(el){ el.textContent = txt; });
      if(t < 1) requestAnimationFrame(step);
 }
    requestAnimationFrame(step);
 }

  function stageDecidedness(){
    stageEnter(stageObserver,4);
    var v = SCANNED_DEC, b = bandOf(v);
    setContent(
      decRailHtml(v) +
      '<div class="vfx" style="margin-top:30px;"><div class="vfx-list" id="decLegend"></div></div>' +
      '<button class="ghost-btn" id="bNext5">다음</button>'
    );
    buildDecLegend(document.getElementById('decLegend'), v);
    wireDecLegend(v);

    // 마커가 0에서 제자리로 걸어가고, 숫자가 그 속도로 따라 오른다
    setTimeout(function(){
      var mark = document.getElementById('dcxMark');
      if(mark) mark.style.left = (v * 100) + '%';
      countUpDec([document.getElementById('dcxVal'),
                  document.getElementById('dcxMarkVal')], v, 1050);
 }, 260);

    document.getElementById('bNext5').onclick = stageImageScan;
 }

  /* =========================================================
     이미지 스캔 — 두상 스캔 데이터
     ========================================================= */

  // 제어점을 지나는 부드러운 곡선. 두상의 세로 프로파일을 만든다.
  function crSpline(cps){
    var us = [], vs = [];
    cps.forEach(function(c){ us.push(c[0]); vs.push(c[1]); });
    return function(u){
      if(u <= us[0]) return vs[0];
      if(u >= us[us.length-1]) return vs[vs.length-1];
      var i = 0; while(i < us.length-2 && u > us[i+1]) i++;
      var t = (u - us[i]) / (us[i+1] - us[i]);
      var p0 = vs[Math.max(0,i-1)], p1 = vs[i], p2 = vs[i+1], p3 = vs[Math.min(vs.length-1,i+2)];
      var t2 = t*t, t3 = t2*t;
      return 0.5*((2*p1) + (-p0+p2)*t + (2*p0-5*p1+4*p2-p3)*t2 + (-p0+3*p1-3*p2+p3)*t3);
 };
 }
  // u=0 턱끝 → u=1 정수리
  var HD_W = crSpline([[0,0.03],[0.05,0.24],[0.13,0.40],[0.24,0.53],[0.36,0.62],
                       [0.48,0.69],[0.60,0.72],[0.72,0.72],[0.84,0.665],[0.93,0.50],[1,0.06]]);
  var HD_D = crSpline([[0,0.24],[0.08,0.42],[0.20,0.56],[0.34,0.70],[0.50,0.80],
                       [0.66,0.86],[0.78,0.845],[0.88,0.74],[0.95,0.52],[1,0.08]]);
  function gz(v, mu, sg){ var d = (v-mu)/sg; return Math.exp(-d*d); }

  function headPt(th, u, M){
    var W = HD_W(u), D = HD_D(u);
    W *= 1 + (M.jaw-1)   * gz(u, 0.30, 0.16);
    W *= 1 + (M.skull-1) * gz(u, 0.78, 0.20);
    D *= 1 + (M.skull-1) * 0.8 * gz(u, 0.74, 0.22);
    W *= 1 + (M.cheek-1) * 0.16 * gz(u, 0.40, 0.14);

    var ct = Math.cos(th), st = Math.sin(th);
    var f = ct > 0 ? ct : 0, b = ct < 0 ? -ct : 0, l = Math.abs(st);
    var f2 = f*f, f3 = f2*f, f4 = f2*f2;

    var X = W*st, Z = D*ct;
    Z *= 1 - 0.13*f*l*l;                              // 얼굴 앞면은 평평하다
    Z += 0.07*f*gz(u, 0.05, 0.09);                    // 턱끝
    Z += 0.045*M.brow*f2*gz(u, 0.665, 0.05);          // 눈썹뼈
    Z -= 0.055*f*Math.sqrt(f)*gz(u, 0.60, 0.045);     // 눈두덩
    Z += 0.20*M.nose*f4*gz(u, 0.50, 0.10);            // 콧대
    Z += 0.085*f4*f4*gz(u, 0.425, 0.035);             // 코끝
    Z -= 0.035*f3*gz(u, 0.385, 0.028);                // 인중
    Z += 0.05*f4*gz(u, 0.302, 0.035);                 // 입술
    Z -= 0.03*f3*gz(u, 0.235, 0.03);                  // 아랫입술 아래
    Z -= 0.055*b*gz(u, 0.70, 0.22);                   // 뒤통수
    var ear = gz(u, 0.545, 0.065) * Math.exp(-Math.pow((ct+0.12)/0.32, 2));
    X += 0.055*ear*(st >= 0 ? 1 : -1);

    return [X, (u*2-1)*0.98*M.len, Z];
 }

  // 얼굴 위에 얹히는 이목구비 선 — (각도, 높이) 로 정의해 두면 두상을 따라 함께 돈다
  function headFeatureCurves(M){
    var out = [], i, s, t, pts;
    function push(fn, n, closed){
      pts = [];
      for(i = 0; i <= n; i++){
        var p = fn(i/n);
        pts.push(headPt(p[0], p[1], M));
 }
      if(closed) pts.push(pts[0]);
      out.push(pts);
 }
    [1,-1].forEach(function(sg){
      var thc = sg*0.40, uc = 0.605;
      push(function(k){ s = k*Math.PI*2;
        return [thc + 0.26*Math.cos(s), uc + 0.030*Math.sin(s)*(0.85+0.15*Math.cos(s))]; }, 40, true);
      push(function(k){ s = k*Math.PI*2;
        return [thc + 0.085*Math.cos(s), uc + 0.011*Math.sin(s)]; }, 22, true);
      push(function(k){ t = k*2-1;
        return [thc + 0.34*t, 0.665 + 0.012*(1-t*t) - 0.007*t*sg]; }, 20);
 });
    push(function(k){ t = k*2-1; return [0.34*t, 0.302 + 0.010*Math.cos(Math.PI*t)]; }, 30);
    push(function(k){ t = k*2-1; return [0.30*t, 0.322 + 0.008*(1-t*t)]; }, 26);
    push(function(k){ t = k*2-1; return [0.30*t, 0.281 - 0.012*(1-t*t)]; }, 26);
    [1,-1].forEach(function(sg){
      push(function(k){ s = k*Math.PI*2;
        return [sg*0.115 + 0.042*Math.cos(s), 0.427 + 0.009*Math.sin(s)]; }, 16, true);
 });
    return out;
 }

  var HD_LAT = 46, HD_LON = 74, HD_N = HD_LAT*HD_LON;

  function buildHead(M){
    var P = new Float32Array(HD_N*3), N = new Float32Array(HD_N*3), i = 0;
    for(var a = 0; a < HD_LAT; a++){
      var u = (a + 0.5)/HD_LAT;
      for(var b = 0; b < HD_LON; b++){
        var p = headPt(b/HD_LON*Math.PI*2, u, M);
        P[i] = p[0]; P[i+1] = p[1]; P[i+2] = p[2];
        var nx = p[0]/0.72, ny = p[1]/1.65, nz = p[2]/0.86;
        var len = Math.sqrt(nx*nx + ny*ny + nz*nz) || 1;
        N[i] = nx/len; N[i+1] = ny/len; N[i+2] = nz/len;
        i += 3;
 }
 }
    return { P:P, N:N, F:headFeatureCurves(M) };
 }

