  function cohortNumbers(p){
    var meta = JOB_META[p.job] || JOB_META.other;
    var ageMul  = { '20':1.12, '30':1.05, '40':0.98, '50':0.90 }[p.age];
    var annual  = 216 * meta.mul * ageMul;
    var saved   = annual * meta.save;
    return { annual:annual, saved:saved, fee:saved*0.10, rate:Math.round(meta.save*100) };
 }
  function cohortLabel(p){
    var meta = JOB_META[p.job] || JOB_META.other;
    var age = { '20':'20대', '30':'30대', '40':'40대', '50':'50대 이상' }[p.age];
    var sex = { f:'여성', m:'남성', n:'' }[p.sex];
    return age + ' ' + (sex ? sex + ' ' : '') + meta.label;
 }

